CREATE TABLE `tblPurchaseDetail` (
  `ID` int(11) NOT NULL AUTO_INCREMENT,
  `PurchaseID` int(11) DEFAULT NULL,
  `StockID` varchar(510) DEFAULT NULL,
  `ICE` tinyint(2) NOT NULL DEFAULT '0' COMMENT '0：没冰;1：有冰',
  `GreenKG` float DEFAULT NULL,
  `LandedKG` float DEFAULT NULL,
  `BinQty` int(11) DEFAULT NULL COMMENT '桶数',
  `Price` float DEFAULT NULL,
  `Total` float DEFAULT NULL,
  `UnloadingDocket` int(11) DEFAULT NULL,
  `is_del` int(2) NOT NULL DEFAULT '0' COMMENT '0：不删除;1：删除',
  `create_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `LandedWeightUnitID` int(11) DEFAULT '1' COMMENT 'LandedKG显示单位',
  `GreenWeightUnitID` int(11) DEFAULT '1' COMMENT 'GreenKG显示单位',
  PRIMARY KEY (`ID`),
  KEY `idx_purchase_detail_stats` (`PurchaseID`,`StockID`,`is_del`),
  KEY `idx_purchase_detail_stock` (`StockID`)
) ENGINE=InnoDB AUTO_INCREMENT=134 DEFAULT CHARSET=utf8mb4;
