DROP TABLE IF EXISTS `tblSupplierStockPrice`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `tblSupplierStockPrice` (
  `PriceID` int(11) NOT NULL AUTO_INCREMENT COMMENT '定价记录唯一主键（自增）',
  `SupplierID` int(11) NOT NULL COMMENT '供应商ID，关联tblSuppliers表的主键',
  `StockID` varchar(510) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '鱼种ID，关联tblStock表的主键',
  `UnitPrice` decimal(10,2) NOT NULL COMMENT '该供应商对应此鱼种的专属单价（保留2位小数，适配金额/重量计价）',
  `Remark` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '定价备注（如"2026年1月协商价""临时优惠价"）',
  `is_del` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否启用：1=启用，0=禁用（保留历史定价，不直接删除）',
  `CreateTime` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '记录创建时间',
  `UpdateTime` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '记录更新时间',
  PRIMARY KEY (`PriceID`),
  KEY `idx_supplier` (`SupplierID`) USING BTREE COMMENT '供应商ID索引（快速查询某供应商的所有定价）',
  KEY `idx_stock` (`StockID`) USING BTREE COMMENT '鱼种ID索引（快速查询某鱼种的所有供应商定价）',
  KEY `idx_is_active` (`is_del`) USING BTREE COMMENT '启用状态索引（快速筛选生效定价）',
  KEY `idx_supplier_active` (`SupplierID`,`is_del`) USING BTREE COMMENT '供应商+启用状态联合索引'
) ENGINE=InnoDB AUTO_INCREMENT=34 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='供应商-鱼种专属定价表（解决不同供应商同鱼种不同价问题）';
